-- V003：商城后台菜单、页面路由与按钮权限；不向普通角色自动授予权限。
SET NAMES utf8mb4;
START TRANSACTION;
SET @gameshop_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='gameshop' LIMIT 1);
SET @gameshop_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@gameshop_root AND path='categories' LIMIT 1);
SET @gameshop_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@gameshop_root AND path='props' LIMIT 1);
SET @gameshop_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@gameshop_root AND path='banners' LIMIT 1);
SET @gameshop_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@gameshop_root AND path='members' LIMIT 1);
SET @gameshop_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@gameshop_root AND path='orders' LIMIT 1);
SET @gameshop_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@gameshop_root AND path='reviews' LIMIT 1);
SET @gameshop_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@gameshop_root AND path='stock-logs' LIMIT 1);
COMMIT;
